<script setup lang="ts">
import type { AdvancedFilter } from './services/voucherSearch'
const props=defineProps<{open:boolean;value:AdvancedFilter}>()
const emit=defineEmits<{close:[];apply:[value:AdvancedFilter]}>()
const draft=reactive<AdvancedFilter>({})
watch(()=>props.open,open=>{if(open){for(const key of Object.keys(draft))delete draft[key as keyof AdvancedFilter];Object.assign(draft,props.value)}})
const error=ref('')
function apply(){for(const [min,max] of [[draft.supplyMin,draft.supplyMax],[draft.vatMin,draft.vatMax]]){if((min&&!/^\d{1,15}$/.test(min))||(max&&!/^\d{1,15}$/.test(max))||(min&&max&&BigInt(min)>BigInt(max))){error.value='금액 범위는 작은 금액부터 원 단위 정수로 입력하세요.';return}}error.value='';emit('apply',{...draft});emit('close')}
</script>
<template><UiModal :open="open" title="전표 상세 검색" @close="emit('close')"><div data-ui-voucher-search-modal class="search-fields"><label data-ui-voucher-search-modal>번호<input data-ui-voucher-search-modal v-model="draft.number" /></label><label data-ui-voucher-search-modal>거래처·사업자번호<input data-ui-voucher-search-modal v-model="draft.partner" /></label><label data-ui-voucher-search-modal>품목<input data-ui-voucher-search-modal v-model="draft.item" /></label><label data-ui-voucher-search-modal>적요·메모<input data-ui-voucher-search-modal v-model="draft.memo" /></label><label data-ui-voucher-search-modal>매출·매입<select data-ui-voucher-search-modal v-model="draft.direction"><option data-ui-voucher-search-modal value="">전체</option><option data-ui-voucher-search-modal value="sales">매출</option><option data-ui-voucher-search-modal value="purchase">매입</option></select></label><label data-ui-voucher-search-modal>유형코드<input data-ui-voucher-search-modal v-model="draft.type" /></label><label data-ui-voucher-search-modal>분개유형<select data-ui-voucher-search-modal v-model="draft.journalType"><option data-ui-voucher-search-modal value="">전체</option><option data-ui-voucher-search-modal v-for="code in ['0','1','2','3','4','5']" :key="code">{{ code }}</option></select></label><label data-ui-voucher-search-modal>전자증빙<select data-ui-voucher-search-modal v-model="draft.electronic"><option data-ui-voucher-search-modal value="">전체</option><option data-ui-voucher-search-modal value="yes">전자</option><option data-ui-voucher-search-modal value="no">종이</option></select></label><label data-ui-voucher-search-modal>공급가액 최소<input data-ui-voucher-search-modal v-model="draft.supplyMin" /></label><label data-ui-voucher-search-modal>공급가액 최대<input data-ui-voucher-search-modal v-model="draft.supplyMax" /></label><label data-ui-voucher-search-modal>부가세 최소<input data-ui-voucher-search-modal v-model="draft.vatMin" /></label><label data-ui-voucher-search-modal>부가세 최대<input data-ui-voucher-search-modal v-model="draft.vatMax" /></label><label data-ui-voucher-search-modal><input data-ui-voucher-search-modal v-model="draft.unbalanced" type="checkbox" />대차 불일치</label><label data-ui-voucher-search-modal><input data-ui-voucher-search-modal v-model="draft.duplicatesOnly" type="checkbox" />중복 의심</label></div><p data-ui-voucher-search-modal v-if="error" role="alert">{{ error }}</p><template #footer><UiButton data-ui-voucher-search-modal @click="emit('apply',{});emit('close')">조건 초기화</UiButton><UiButton data-ui-voucher-search-modal @click="apply">검색 적용</UiButton></template></UiModal></template>
